import { Host, h, Component, Prop, type ComponentInterface } from '@stencil/core';
import { useIcon } from '../runtime';

@Component({
  tag: 'ks-icon-tablet',
  styleUrls: ['../styles/index.css'],
  shadow: true,
})
export class KsIconTablet implements ComponentInterface {
  ['ks-icon-name']: string = 'ks-icon-tablet';

  @Prop() size: string | number = 16;
  @Prop() color: string = 'currentColor';
  /**
   * @deprecated
   */
  @Prop() strokeWidth: string | number;
  /**
   * @deprecated
   */
  @Prop() absoluteStrokeWidth: boolean = false;

  render() {
    const icon = useIcon({ size: this.size, color: this.color });

    return (
      <Host class="ks-icon" ks-icon>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={icon.width}
          height={icon.height}
          viewBox="0 0 48 48"
          fill="none"
          stroke-width={icon.strokeWidth}
          stroke={icon.color}
        >
          <rect x="43.5" y="10.5" width="27" height="39" rx="1.5" transform="rotate(90 43.497 10.5)"></rect>
          <path d="M10.49 21.73v6" stroke-linecap="round"></path>
        </svg>
      </Host>
    );
  }
}
